local PatrolMapCellNode = Class("PatrolMapCellNode")
function PatrolMapCellNode:__init()
    self.preEventPoint = nil
    self.currentEventPoint = nil
    self.nextEventPoint = nil
end

function PatrolMapCellNode:__delete()
    self.preEventPoint = nil
    self.currentEventPoint = nil
    self.nextEventPoint = nil

    self.controller = nil
end

function PatrolMapCellNode:Awake()

end

function PatrolMapCellNode:FreshBaseUI(data)
    local isLow = true--MazeMgr.currentFloor <= 15
    local isMiddle = MazeMgr.currentFloor > 15 --and MazeMgr.currentFloor <= 30
    local isHigh = MazeMgr.currentFloor > 30 --and MazeMgr.currentFloor <= 45
    KTool.SetActive(self.ImgLine1, isLow)
    KTool.SetActive(self.ImgLine2, isMiddle)
    KTool.SetActive(self.ImgLine3, isHigh)
    SetButtonAction(self.BtnReward15, function ()
        if data.isMain then
            self:BtnActionRewardBox(self.BtnReward15.gameObject)
        end
    end)
    SetButtonAction(self.BtnReward30, function ()
        if data.isMain then
            self:BtnActionRewardBox(self.BtnReward30.gameObject)
        end
    end)
    SetButtonAction(self.BtnReward45, function ()
        if data.isMain then
            self:BtnActionRewardBox(self.BtnReward45.gameObject)
        end
    end)
    ---@region前一步事件点
    if MazeMgr.currentFloor > 1 then
        if data.isMain then
            if isNull(self.preEventPoint) then
                self.preEventPoint = CfUtils.InstantiateGo(self.PatrolPointContentNode, self.PointPositionGroup1)
                self.preEventPoint.name = "preEventPoint"
            end
            local preEventPointEnv = CfUtils.GetLuaScr(self.preEventPoint, "Game.UI.Patrol.PatrolPointContentNode")
            local currentData = {
                isCurrent = true,
                isPre = true,
                isMain = data.isMain,
                key = data.key,
                posGroup = self.PointPositionGroup1
            }
            KTool.SetActive(self.preEventPoint, true)
            preEventPointEnv:FreshBaseUI(currentData)
        else
            if self.preEventPoint then
                KTool.SetActive(self.preEventPoint, false)
            end
        end

    end
    ---@endregion
    ---@region当前事件点
    if isNull(self.currentEventPoint) then
        self.currentEventPoint = CfUtils.InstantiateGo(self.PatrolPointContentNode, data.isMain and self.PointPositionGroup1 or self.PointPositionGroup2)
        self.currentEventPoint.name = "currentEventPoint"
    end
    local currentEventPointEnv = CfUtils.GetLuaScr(self.currentEventPoint, "Game.UI.Patrol.PatrolPointContentNode")
    local currentData = {
        isCurrent = true,
        isMain = data.isMain,
        key = data.key,
        posGroup = data.isMain and self.PointPositionGroup1 or self.PointPositionGroup2--改为只有主页的当前事件点用第一组坐标
    }
    --print(self.currentEventPoint.gameObject.name.."--00-->>"..tostring(self.currentEventPoint.gameObject.activeInHierarchy))

    KTool.SetActive(self.currentEventPoint, true)
    --print(self.currentEventPoint.gameObject.name.."--11-->>"..tostring(self.currentEventPoint.gameObject.activeInHierarchy))

    currentEventPointEnv:FreshBaseUI(currentData)
    --print(self.currentEventPoint.gameObject.name.."--22-->>"..tostring(self.currentEventPoint.gameObject.activeInHierarchy))

    ---@endregion
    ---@region下一步事件点
    if MazeMgr.currentFloor == MazeMgr:GetMaxFloor() then
        if not isNull(self.nextEventPoint) then
            KTool.SetActive(self.nextEventPoint, false)
        end
    else
        if isNull(self.nextEventPoint) then
            self.nextEventPoint = CfUtils.InstantiateGo(self.PatrolPointContentNode, self.PointPositionGroup2)
            self.nextEventPoint.name = "nextEventPoint"
        end
        local nextEventPointEnv = CfUtils.GetLuaScr(self.nextEventPoint, "Game.UI.Patrol.PatrolPointContentNode")
        local nextData = {
            isCurrent = false,
            isMain = data.isMain,
            key = data.key,
            posGroup = self.PointPositionGroup2
        }
        nextEventPointEnv:FreshBaseUI(nextData)
        KTool.SetActive(self.nextEventPoint, true)
    end
    ---@endregion
    if data.isMain then

    else
        local pointGo = self.PointPositionGroup2.transform:Find(tostring(MazeMgr.currentFloor + 1))--下一步目标点的位置
        local pointGo2 = self.PointPositionGroup2.transform:Find(tostring(MazeMgr.currentFloor))--当前目标点的位置
        local centerPos
        if pointGo then
            centerPos = Vector2.New((pointGo.transform.anchoredPosition.x + pointGo2.transform.anchoredPosition.x)/2*2, (pointGo.transform.anchoredPosition.y + pointGo2.transform.anchoredPosition.y)/2*2)--由于地图放大了两倍，所以将得出的坐标乘2
        else
            centerPos = pointGo2.transform.anchoredPosition
        end
        --self.controller.transform. = pointGo.transform.localPosition
        self.controller.transform.anchoredPosition = - centerPos

    end
end

function PatrolMapCellNode:BtnActionRewardBox(gameObject)
    local rewardsData = MazeMgr:GetQuestRewardBox()
    GameUtils.ShowCommonTipsBoardRewardPreview(gameObject, rewardsData, localize('奖励预览:'), false)
end

function PatrolMapCellNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return PatrolMapCellNode